#include <vector>
#include <omp.h>

bool reduceLogicalXOR(std::vector<bool> const& x) {
  const std::size_t n = x.size();
  int xor_int = 0; // use int for OpenMP reduction portability

#pragma omp parallel for reduction(^ : xor_int)
  for (std::size_t i = 0; i < n; ++i) {
    xor_int ^= (x[i] ? 1 : 0);
  }

  return xor_int != 0;
}
